package com.dawnrise.identity.notification.controller;
import org.springframework.jdbc.core.namedparam.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1/notification-recipients") @PreAuthorize("hasRole('INTERNAL_SERVICE')") public class InternalNotificationRecipientController {private final NamedParameterJdbcTemplate jdbc;public InternalNotificationRecipientController(NamedParameterJdbcTemplate jdbc){this.jdbc=jdbc;}@GetMapping("/has-action")public Response has(@RequestParam long organizationId,@RequestParam long userId,@RequestParam String actionType,@RequestParam long referenceId){Integer count=jdbc.queryForObject("SELECT COUNT(*) FROM notification_recipients r JOIN notification_events e ON e.id=r.event_id AND e.organization_id=r.organization_id WHERE r.organization_id=:org AND r.user_id=:user AND e.action_type=:type AND e.action_reference_id=:ref",new MapSqlParameterSource("org",organizationId).addValue("user",userId).addValue("type",actionType).addValue("ref",referenceId),Integer.class);return new Response(count!=null&&count>0);}public record Response(boolean allowed){}}
